'use strict';
const UI3={bind,render,peopleView,rivalsView,coffeeView,boardView,help};
let liveStore=state.stores[0].id,liveFrame=12,replayTimer=null,replayPaused=Boolean(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches);
const KPI4={lostRate:'Podíl ztracených hostů',guests:'Obsloužení hosté',quality:'Kvalita provozu',loyalty:'Věrnost hostů',profit:'Zisk pobočky'};
function kpiValue4(metric,value){return metric==='lostRate'?number(value*100,1)+' %':metric==='profit'?money(value):number(value,1)}
function planCard4(p){const a=p.action,reviewed=p.status==='reviewed';return `<article class="card plan-card"><span class="badge">${p.status==='proposed'?'Čeká na rozhodnutí':p.status==='active'?'Probíhá do týdne '+p.dueReview:reviewed?(p.success?'Cíl splněn':'Cíl nesplněn'):'Odmítnuto'}</span><h3>${esc(a.title)}</h3><p class="sub">${loc(p.store).city} · ${loc(p.store).name} · ${esc(p.name)}</p>${rows([['Jednorázová investice',money(a.cost)],['Další týdenní náklad',money(a.weekly)],[KPI4[a.metric]+' dnes',kpiValue4(a.metric,p.baseline[a.metric])],['Slíbený cíl za 4 týdny',kpiValue4(a.metric,a.targetValue)],...(reviewed?[['Průměr dosažených výsledků',kpiValue4(a.metric,p.actual)]]:[])])}${p.status==='proposed'?`<p class="sub">Rozhodnutí do týdne ${p.due}. Cíl je odhad; trh a tvoje další změny ovlivní výsledek.</p><div class="actions"><button class="primary" data-plan-approve="${p.id}" ${state.cash<a.cost+a.weekly*2?'disabled':''}>Schválit plán</button><button class="soft" data-plan-decline="${p.id}">Odmítnout</button></div>`:p.status==='active'?'<p class="sub">Vedení sbírá výsledky. Schválený tým nebo marketing se během čtyř týdnů automaticky nepřepočítává.</p>':''}</article>`}
const STORY4={rest:{title:'Prostor pro odpočinek',text:'Dlouhodobé přetížení začíná ohrožovat spokojenost. Podpora sníží přetížení o 25 bodů; dva týdny bude kapacita obsluhy o 6 % nižší.',support:'Odlehčit práci · 8 000 Kč'},ambition:{title:'Chci vést celý region',text:'Člověk žádá cestu do regionálního vedení. Příslib povýšení do osmi týdnů zlepší vztah; nesplněný slib sníží spokojenost o 18 bodů.',support:'Slíbit povýšení do 8 týdnů'},craft:{title:'Prostor pro vlastní produkt',text:'Specialista navrhuje tvůrčí školení. Podpora zvýší dovednost produktu o 3 body a spokojenost o 8.',support:'Podpořit rozvoj · 12 000 Kč'},mentoring:{title:'Předám svoje zkušenosti',text:'Mentor chce rozvíjet kolegu. Sám získá 3 body vedení lidí, nejméně zkušený kolega další 2.',support:'Zahájit mentoring · 12 000 Kč'}};
function leadershipView(){const e=state.empire,done=e.planHistory.filter(p=>p.status==='reviewed'),rate=done.length?round(done.filter(p=>p.success).length/done.length*100):null;return `<div class="split"><section class="card guide"><span class="eyelabel">OD NÁVRHU K ODPOVĚDNOSTI</span><h2>Vedení skládá účty.</h2><p>Manažer ukáže problém, navrhne změnu a slíbí měřitelný cíl. Po čtyřech výsledcích se porovná průměr s příslibem. Board sleduje úspěšnost posledních plánů.</p>${rows([['Návrhy čekající na rozhodnutí',e.plans.filter(p=>p.status==='proposed').length],['Aktivní plány',e.plans.filter(p=>p.status==='active').length],['Dokončené plány',done.length],['Úspěšnost',rate===null?'Zatím bez výsledků':rate+' %']])}<button class="soft" data-goto="board">Pohled boardu →</button></section><section class="card"><h2>Pravomoc realizovat plány</h2><label class="checkbox-line"><input id="autoPlans4" type="checkbox" ${e.autoPlans?'checked':''}> Dovolit vedení schvalovat vlastní návrhy</label>${field('Limit jednorázové investice (Kč)',input('planLimit4',e.planLimit,0,200000,1000))}<p class="sub">Automatika musí zachovat tři týdenní rezervy a navíc krytí tří týdnů nových nákladů. Výsledky zůstávají viditelné. Návrhy vznikají každé čtyři týdny; současně čekají nejvýše čtyři.</p><p class="sub">Návrh kontroluje platnost autora i aktuální vybavení. Můžeš ho odmítnout nebo provést vlastní změnu.</p></section></div><div class="section-header"><h2>Návrhy a probíhající plány</h2></div><div class="cards">${e.plans.map(planCard4).join('')||empty('Po několika týdnech manažeři navrhnou další krok podle skutečných výsledků. Najmi vedení kavárny a odehraj první provozní týdny.')}</div><div class="section-header"><h2>Lidé ve firmě mají svoje cíle</h2></div><div class="cards">${e.stories.map(s=>{const c=STORY4[s.type];return `<article class="card"><span class="badge">Do týdne ${s.due}</span><h3>${esc(s.name)} · ${c.title}</h3><p>${c.text}</p><div class="stack"><button class="primary" data-story="${s.id}" data-story-answer="support">${c.support}</button><button class="soft" data-story="${s.id}" data-story-answer="bonus">Jednorázový bonus · 8 000 Kč</button><button class="soft" data-story="${s.id}" data-story-answer="decline">Návrh odmítnout</button></div></article>`}).join('')||empty('Nové osobní zprávy přicházejí přibližně každých dvanáct týdnů podle přetížení a povahy lidí.')}</div><div class="section-header"><h2>Výsledky vedení</h2></div><div class="cards">${e.planHistory.slice(0,8).map(planCard4).join('')||empty('Po dokončení prvního plánu se objeví slíbený a dosažený výsledek.')}</div>${e.storyHistory.length?`<section class="card" style="margin-top:24px"><h3>Historie vztahů</h3>${rows(e.storyHistory.slice(0,8).map(s=>[esc(s.name)+' · '+STORY4[s.type].title,'Týden '+s.closed+' · '+({support:'Podpořeno',bonus:'Bonus',decline:'Odmítnuto'})[s.choice]+' · '+money(s.cost)]))}</section>`:''}`}
function liveScene4(s){const frame=replayFrame4(s.id,liveFrame),tables=Math.min(8,Math.ceil(s.seats/6));return `<svg id="liveScene" viewBox="0 0 800 460" role="img" aria-label="Schéma kavárny ${esc(loc(s.id).name)}, hosté, fronta a baristé"><defs><pattern id="floor4" width="32" height="32" patternUnits="userSpaceOnUse"><rect width="32" height="32" fill="#ece5d5"/><path d="M0 0H32V32" fill="none" stroke="#e1d5bf" stroke-width="1"/></pattern></defs><rect x="28" y="24" width="744" height="408" rx="14" fill="url(#floor4)" stroke="#b4ad96" stroke-width="10"/><rect x="26" y="330" width="14" height="68" fill="#fffdf8"/><text x="60" y="414" class="scene-label">VCHOD</text><rect x="330" y="66" width="380" height="75" rx="8" fill="#49664f"/><rect x="350" y="82" width="80" height="36" rx="5" fill="#d1d6c7"/><rect x="450" y="82" width="35" height="36" rx="4" fill="#bd9b65"/><rect x="505" y="82" width="55" height="36" rx="5" fill="#a4b79b"/><text x="350" y="60" class="scene-label">${s.equipment.bar?'EFEKTIVNÍ BAR':'VÝDEJ & PŘÍPRAVA'}</text>${s.equipment.oven?'<rect x="600" y="80" width="78" height="38" rx="5" fill="#d7bd86"/><text x="612" y="105" font-size="10" fill="#4c513f">PEČIVO</text>':''}<path d="M70 360L155 245L310 245L395 183" fill="none" stroke="#b8b395" stroke-width="3" stroke-dasharray="8 7"/><text x="132" y="175" class="scene-label">FRONTA</text>${Array.from({length:tables},(_,i)=>{const x=470+(i%4)*76,y=280+Math.floor(i/4)*67;return `<g><circle cx="${x}" cy="${y}" r="20" fill="#caaa79" stroke="#a98c61" stroke-width="2"/><rect x="${x-27}" y="${y-8}" width="10" height="16" rx="3" fill="#647957"/><rect x="${x+17}" y="${y-8}" width="10" height="16" rx="3" fill="#647957"/></g>`}).join('')}<text x="475" y="392" class="scene-label">${s.seats} MÍST · ${LAYOUT[s.layout].toUpperCase()}</text><rect x="65" y="60" width="170" height="65" rx="6" fill="#fbf8ef" stroke="#c5c6b4"/><text x="80" y="82" class="scene-label">DNEŠNÍ NABÍDKA</text><text x="80" y="104" font-size="12" fill="#49614b">${menuSummary(s).drinks.length} nápoje · ${number(menuSummary(s).minutes,1)} min přípravy</text>${Array.from({length:Math.min(7,s.staff)},(_,i)=>`<g class="scene-worker" transform="translate(${340+i*47} 157)"><circle r="9" fill="#cda783"/><path d="M-9 9H9L12 29H-12Z" fill="#264b3b"/><circle cy="3" r="2" fill="#5f4737"/></g>`).join('')}<g id="sceneGuests">${guestSvg4(frame)}</g></svg><div class="scene-hud"><span>Fronta <strong id="liveQueue">${frame.queue}</strong></span><span>U baru <strong id="liveWorking">${frame.working}</strong></span><span>Odcházejí <strong id="liveLost">${frame.lost}</strong></span><span>Okamžik <strong id="liveMoment">${liveFrame}</strong>/120</span></div>`}
function guestSvg4(frame){return frame.people.map(p=>`<g class="scene-guest ${p.stage==='lost'?'leaving':''}" transform="translate(${p.x} ${p.y})"><circle r="8" fill="#c99e79"/><path d="M-8 8H8L10 25H-10Z" fill="${p.stage==='lost'?'#b66c50':['#81985b','#788e9b','#be9270','#9c8caa'][p.id%4]}"/>${p.stage==='seat'?'<circle cx="13" cy="12" r="4" fill="#fffdf8"/>':''}${p.stage==='lost'?'<text x="9" y="-5" font-size="12" fill="#a34d35">!</text>':''}</g>`).join('')}
function liveView(){const s=state.stores.find(s=>s.id===liveStore)||state.stores[0];liveStore=s.id;const o=s.operations;return `<div class="view-toolbar"><p class="intro">Pohled do provozu ukazuje frontu, práci baru a hosty u stolů. Přehrávka vychází z výsledků posledního týdne.</p>${field('Kavárna',`<select id="liveStore4">${storeOptions(s.id)}</select>`)}</div><div class="live-layout"><section class="card live-card">${liveScene4(s)}<div class="actions"><button class="primary" id="replayToggle4">${replayPaused?'Spustit':'Pozastavit'} přehrávku</button><button class="soft" id="replayStep4">Další okamžik</button><button class="soft" id="replayReset4">Od začátku</button></div><p class="sub">Jedna postava zastupuje skupinu hostů. Jde o přehrávku výsledku tahu; další peníze ani zásoby se při ní nespotřebovávají.</p></section><section class="card"><span class="eyelabel">${s.last?'POSLEDNÍ TÝDEN':'PROVOZ ČEKÁ NA PRVNÍ TAH'}</span><h2>${loc(s.id).name}</h2>${rows([['Obsloužení hosté',s.last?o.served:'—'],['Ztracení kvůli zásobám',s.last?o.stockLost:'—'],['Ztracení kvůli kapacitě',s.last?o.capacityLost:'—'],['Odhad čekání',s.last?number(o.wait,1)+' min':'—'],['Průměrné využití sezení',s.last?o.occupied+' %':'—'],['Baristé na směně',s.staff],['Čas přípravy / host',number(menuSummary(s).minutes,2)+' min']])}<p class="sub">${s.last?esc(s.last.reason):'Odehraj týden a sleduj, co omezilo obsluhu.'}</p><div class="actions"><button class="soft" data-goto="menu">Menu a vybavení</button><button class="soft" data-goto="leadership">Návrhy vedení</button></div></section></div>`}
function stopReplay4(){if(replayTimer!==null){window.clearInterval(replayTimer);replayTimer=null}}
function drawReplay4(){const s=state.stores.find(s=>s.id===liveStore);if(!s||!el('sceneGuests'))return;const f=replayFrame4(s.id,liveFrame);el('sceneGuests').innerHTML=guestSvg4(f);el('liveQueue').textContent=f.queue;el('liveWorking').textContent=f.working;el('liveLost').textContent=f.lost;el('liveMoment').textContent=liveFrame;}
function startReplay4(){stopReplay4();if(replayPaused||view!=='live')return;replayTimer=window.setInterval(()=>{if(view!=='live'){stopReplay4();return}liveFrame=(liveFrame+1)%121;drawReplay4()},450)}
function labView(){return `<div class="view-toolbar"><p class="intro">Upraž malou šarži, otestuj ji na různých hostech a teprve potom změň prodejní recepturu.</p><button class="primary" id="newTrial4">Nový experiment +</button></div><div class="split"><section class="card guide"><span class="eyelabel">OD NÁPADU K PODPISOVÉ KÁVĚ</span><h2>Chuť má svoje publikum.</h2><p>Receptura používá skutečná zelená zrna a volnou kapacitu pražírny. Experimentální káva zůstává oddělená. Degustace přijde další týden a ukáže přijetí kancelářemi, komunitou, turisty, studenty a milovníky výběrové kávy.</p><p>Uvedení změní další pražení. Dřívější šarže drží svůj profil, cenu a datum pražení. Prodej reaguje na chuť skutečné zásoby.</p></section><section class="card"><h2>Pravidla laboratoře</h2>${rows([['Velikost testovací šarže','5–30 kg zelené kávy'],['Degustace',money(8000)+' + skutečné pražení'],['Rozpracované šarže',state.empire.trials.filter(t=>!['released','expired'].includes(t.status)).length+' / 8'],['Čerstvost','Nejvýše 8 týdnů'],['Soutěž',money(18000)+' · jednou za 26 týdnů']])}<p class="sub">Produkt zmenšuje nejistotu degustace a pomáhá v soutěži. Výsledky jsou hodnocení herních segmentů. Degustace může zjistit i méně vhodnou recepturu.</p><button class="soft" data-goto="roasters">Zrna a kapacita →</button></section></div><div class="section-header"><h2>Experimentální šarže</h2></div><div class="cards">${state.empire.trials.slice().reverse().map(t=>`<article class="card"><span class="badge">${({testing:'Degustace v týdnu '+t.due,ready:'Připraveno k uvedení',released:'Uvedeno do nabídky',expired:'Odepsáno'})[t.status]}</span><h3>${esc(t.name)}</h3><p class="sub">${t.recipe.share} % ${ORIGINS[t.recipe.primary].name} · ${100-t.recipe.share} % ${ORIGINS[t.recipe.secondary].name} · ${['','Světlé','Střední','Tmavé'][t.recipe.roast]} pražení</p>${rows([['Šarže',number(t.lot.kg,1)+' kg · '+t.lot.zone],['Stáří',state.week-t.lot.roastedWeek+' týdnů'],['Náklad / kg',money(t.lot.cost)],...(t.scores?Object.entries(t.scores).map(([k,n])=>[SEGMENTS[k].name,n+'/100']):[])])}${t.status==='ready'?`<button class="primary wide" data-release-trial="${t.id}">Uvést jako podpisovou recepturu</button>`:''}</article>`).join('')||empty('Začni malou změnou poměru nebo pražení a porovnej přijetí hosty.')}</div><div class="section-header"><h2>Podpisové receptury & ocenění</h2></div><div class="cards">${state.blends.filter(b=>b.signature).map(b=>`<article class="card"><span class="badge">${esc(b.signature.award||'Otestovaná receptura')}</span><h3>${esc(b.name)}</h3>${rows(Object.entries(b.signature.scores).map(([k,n])=>[SEGMENTS[k].name,n+'/100']))}<button class="soft wide" data-competition="${b.id}" ${b.signature.competitionWeek&&state.week-b.signature.competitionWeek<26?'disabled':''}>Přihlásit do soutěže · 18 000 Kč</button></article>`).join('')||empty('Po uvedení experimentu vznikne podpisová káva vhodná do soutěže.')}</div>`}
function trialDialog4(){show(`<span class="eyelabel">MALÁ ŠARŽE, SKUTEČNÁ ZRNA</span><h2>Experimentální receptura</h2><div class="fields">${field('Název',`<input id="trialName4" maxlength="40" value="Nová podpisová káva">`)}${field('Nahrazovaná receptura',`<select id="trialBlend4">${blendOptions(state.blends[0].id)}</select>`)}${field('Pražírna',`<select id="trialRoaster4">${state.roasters.map(r=>option(r.id,r.name+' · '+r.zone,state.roasters[0].id)).join('')}</select>`)}${field('Zelená káva (kg)',input('trialKg4',10,5,30))}${field('Hlavní původ',`<select id="trialPrimary4">${Object.entries(ORIGINS).map(([k,o])=>option(k,o.name,'ethiopia')).join('')}</select>`)}${field('Druhý původ',`<select id="trialSecondary4">${Object.entries(ORIGINS).map(([k,o])=>option(k,o.name,'colombia')).join('')}</select>`)}${field('Podíl hlavního původu (%)',input('trialShare4',75,0,100))}${field('Pražení',`<select id="trialRoast4">${option(1,'Světlé',1)}${option(2,'Střední',1)}${option(3,'Tmavé',1)}</select>`)}</div><p class="sub">Zrna musí být na skladě. Degustace 8 000 Kč, pražení 55 Kč/kg; výrobní směny i sklad musí mít místo. Další týden uvidíš výsledky.</p><button class="primary wide" id="trialConfirm4">Upražit experiment</button>`);el('trialConfirm4').onclick=()=>{try{startTrial4({name:el('trialName4').value,blend:el('trialBlend4').value,roaster:el('trialRoaster4').value,kg:Number(el('trialKg4').value),primary:el('trialPrimary4').value,secondary:el('trialSecondary4').value,share:Number(el('trialShare4').value),roast:Number(el('trialRoast4').value)});persist();render();el('modal').close();toast('Experimentální šarže připravena.')}catch(e){toast(e.message)}};}
function marketsView(){const e=state.empire,p=e.publicCompany,c=e.covenant,cycle=economy4(),average=state.history.slice(-4).reduce((a,h)=>a+h.profit,0)/Math.max(1,state.history.slice(-4).length);return `<div class="split"><section class="card guide"><span class="eyelabel">HOSPODÁŘSKÝ CYKLUS</span><h2>${cycle.name}</h2>${rows([['Poptávka trhu',round(cycle.demand*100)+' %'],['Cena vstupů',round(cycle.input*100)+' %'],['Další změna','Týden '+e.nextCycle],['Koordinace sítě / týden',money(overhead4())],['Průměrný zisk / 4 týdny',money(average)]])}<p>Trh střídá růst, stabilitu, drahé vstupy a slabší poptávku po třinácti týdnech. Obsazená města mají menší prostor pro další prodeje. IT a regionální vedení snižují náklady koordinace.</p><button class="soft" data-goto="planner">Prověřit investici →</button></section><section class="card"><h2>Úvěrové podmínky</h2>${rows([['Dluh',money(state.debt)],['Požadovaná dvoutýdenní rezerva',money(weeklyFixed()*2)],['Růstová smlouva',c?'Aktivní':'Žádná'],...(c?[['Stav smlouvy',c.warningDue?'Náprava do týdne '+c.warningDue:'Podmínky splněny'],['Poslední poplatek',money(c.fee)]]:[])])}<button class="soft wide" id="growthLoan4" ${c||state.stores.length<5?'disabled':''}>Růstový úvěr · +2 miliony Kč</button><p class="sub">Vyžaduje pět poboček. Vedle běžného úroku dodržuj rezervu a nezáporný průměr zisku. Na nápravu máš čtyři týdny; při trvajícím porušení poplatek 2 % dluhu, nejvýše 40 000 Kč, každé čtyři týdny.</p><button class="quiet" data-goto="finance">Běžné úvěry a splácení →</button></section></div><section class="card" style="margin-top:24px"><div class="card-head"><div><span class="eyelabel">VEŘEJNÁ FIRMA</span><h2>${p?'Investoři očekávají výsledky':'Vstup na burzu'}</h2></div><span class="badge">Podíl zakladatele ${state.founderShare} %</span></div>${p?`<div class="split"><div>${rows([['Veřejný podíl',p.shares+' %'],['Důvěra investorů',p.confidence+'/100'],['Modelová cena akcie',money(p.price)],['Kapitál získaný při vstupu',money(p.capital)],['Další kvartální vyhodnocení','Týden '+p.quarter]])}<button class="soft" id="buyback4" ${!p.shares?'disabled':''}>Odkoupit zpět 1 % · ${money(Math.max(1000000,companyValue())*.01)}</button></div><div>${field('Závazek pro tento kvartál',`<select id="investorTarget4" ${state.week!==p.targetWindow?'disabled':''}>${option('margin','Udržet provozní marži alespoň 15 %',p.target)}${option('growth','Otevřít alespoň dvě další pobočky',p.target)}</select>`)}<p class="sub">Závazek volíš pouze v prvním týdnu kvartálu. Nesplnění sníží důvěru investorů o 12 bodů a důvěru boardu o 4. Pod 50 % zakladatelského podílu potřebuje velká expanze mandát boardu.</p>${p.lastReview?`<div class="warning">Týden ${p.lastReview.week}: ${p.lastReview.passed?'Cíl splněn':'Cíl nesplněn'} · marže ${number(p.lastReview.margin*100,1)} %.</div>`:''}</div></div>`:`<p class="sub">Osm poboček, nejméně dvanáct týdenních výsledků, čtyři ziskové týdny, dva lidé ve Financích a alespoň 20 % zakladatelského podílu. Poplatek 200 000 Kč; firma získá 20 % své odhadované hodnoty za dvacet procentních bodů.</p><button class="primary" id="ipo4" ${state.stores.length<8||state.history.length<12||state.departments.finance<2||state.founderShare<20?'disabled':''}>Uvést firmu na burzu</button>`}<p class="sub" style="margin-top:18px">Akcie a ocenění jsou součástí herní ekonomiky. Kapitálové transakce mění hotovost i rozhodovací kontrolu.</p></section><section class="card" style="margin-top:24px"><h2>Obsazenost jednotlivých trhů</h2><div class="table-scroll"><table class="data"><thead><tr><th>Město</th><th>Tvoje pobočky</th><th>Soupeři</th><th>Obsazenost adres</th><th>Vliv na poptávku</th></tr></thead><tbody>${CITIES.map(c=>{const m=cityPressure4(c.name);return `<tr><td>${c.name}</td><td>${m.player}</td><td>${m.rivals}</td><td>${round(m.occupancy*100)} %</td><td>${round(m.factor*100)} %</td></tr>`}).join('')}</tbody></table></div></section><section class="card" style="margin-top:24px"><h2>Nájemní smlouvy</h2>${rows(state.stores.map(s=>[loc(s.id).city+' · '+loc(s.id).name,money(s.lease.rent)+'/týden · obnova v týdnu '+s.lease.due]))}<p class="sub">Obnova po 26 týdnech promítá situaci na trhu a obsazenost města. Nová sazba se skutečně započítá do nákladů dané pobočky.</p></section>`}
peopleView=function(){return `<section class="card" style="margin-bottom:24px"><h2>Povaha & dlouhodobé vztahy</h2>${rows(staffAssignments().map(a=>{const p=a.person;return [esc(p.name)+' · '+TRAITS4[p.life.trait],'Přetížení '+round(p.life.burnout)+'/100'+(p.life.promotionDue?' · slíbené povýšení do '+p.life.promotionDue:'')]}))}<p class="sub">Mentor zlepšuje motivaci týmu, kávový specialista přidává dva body kvality pražení. Přetížení nad 60 snižuje spokojenost. Osobní sliby mají termíny i následky.</p><button class="soft" data-goto="leadership">Příběhy a závazky vedení →</button></section>`+UI3.peopleView()};
rivalsView=function(){return `<div class="cards" style="margin-bottom:24px">${state.rivals.map(r=>{const b=r.business,c=RIVAL4[r.id]||{ceo:r.name,title:'Vlastní strategie'};return `<section class="card strategy-card"><span class="eyelabel">${esc(c.ceo)} · CEO</span><h3>${esc(r.name)}</h3><p>${c.title}</p>${rows([['Kvalita nabídky',b.quality+'/100'],['Velkoobchodní účty',b.accounts+' / '+b.accountCapacity],['Příští strategické rozhodnutí','Týden '+b.expansionDue],['Poslední přijaté rozhodnutí',esc(b.decisions[0]?.text||'Analýza trhu')]])}${b.campaign?`<div class="warning">Aktivní kampaň: ${b.campaign.city} do týdne ${b.campaign.until}. Konkurenční tlak na tvé hosty.</div>`:''}<details><summary>Důvody a historie rozhodnutí</summary>${b.decisions.slice(0,6).map(d=>`<p class="sub"><strong>Týden ${d.week} · ${esc(d.text)}</strong><br>${esc(d.detail)}</p>`).join('')||'<p class="sub">Po prvním rozhodnutí uvidíš investici, očekávaný výnos a zvolený cíl.</p>'}</details></section>`}).join('')}</div>${state.empire.partnership?`<section class="card" style="margin-bottom:24px"><h3>Nabídka obchodního partnerství</h3><p>${esc(state.rivals.find(r=>r.id===state.empire.partnership.rival)?.name)} chce odebírat ${state.empire.partnership.kg} kg týdně za ${money(state.empire.partnership.price)}/kg. Rozhodnutí do týdne ${state.empire.partnership.due}. Smlouva běží dvanáct týdnů a potřebuje volného obchodníka.</p><div class="actions"><button class="primary" id="partnership4">Přijmout partnerství</button><button class="soft" id="declinePartnership4">Odmítnout</button></div></section>`:''}${UI3.rivalsView().replace('Každý týden platí náklady; každé čtyři týdny hledají novou lokalitu.','Každý týden platí náklady; další investice vybírají podle své strategie, odhadu návratnosti a rezervy.')}`};
boardView=function(){const done=state.empire.planHistory.filter(p=>p.status==='reviewed').slice(0,8);return `<section class="card" style="margin-bottom:24px"><h3>Board sleduje výsledky slíbených plánů</h3><p class="sub">${done.length?done.filter(p=>p.success).length+' z '+done.length+' posledních plánů splnilo svůj cíl. Pod 50 % úspěšnosti po třech vyhodnoceních provozní ředitel nepodpoří další expanzi.':'Vedení zatím nemá vyhodnocené plány. Původní finanční a provozní kritéria zůstávají viditelná u každého hlasu.'}</p><button class="soft" data-goto="leadership">Otevřít výsledky vedení →</button></section>`+UI3.boardView()};
bind=function(){UI3.bind();if(el('liveStore4'))el('liveStore4').onchange=()=>{liveStore=el('liveStore4').value;liveFrame=12;render()};if(el('replayToggle4'))el('replayToggle4').onclick=()=>{replayPaused=!replayPaused;render()};if(el('replayStep4'))el('replayStep4').onclick=()=>{replayPaused=true;stopReplay4();liveFrame=(liveFrame+1)%121;render()};if(el('replayReset4'))el('replayReset4').onclick=()=>{liveFrame=0;render()};if(el('autoPlans4'))el('autoPlans4').onchange=()=>act(()=>{guard();state.empire.autoPlans=el('autoPlans4').checked},'Pravomoc vedení upravena.');if(el('planLimit4'))el('planLimit4').onchange=()=>act(()=>{guard();const n=Number(el('planLimit4').value);if(!Number.isInteger(n)||n<0||n>200000)throw Error('Limit musí být 0–200 000 Kč.');state.empire.planLimit=n},'Limit plánů uložen.');on('[data-plan-approve]',b=>{const p=state.empire.plans.find(p=>p.id===b.dataset.planApprove);confirmAction('Schválit plán vedení?',esc(p.action.title)+'. Investice '+money(p.action.cost)+' a další náklad '+money(p.action.weekly)+'/týden. Za čtyři výsledky se porovná slíbený a dosažený cíl.',()=>decidePlan4(p.id,true),'Schválit plán')});on('[data-plan-decline]',b=>act(()=>decidePlan4(b.dataset.planDecline,false),'Plán odmítnut.'));on('[data-story]',b=>act(()=>resolveStory4(b.dataset.story,b.dataset.storyAnswer),'Osobní zpráva vyřízena.'));if(el('newTrial4'))el('newTrial4').onclick=trialDialog4;on('[data-release-trial]',b=>{const t=state.empire.trials.find(t=>t.id===b.dataset.releaseTrial);confirmAction('Uvést recepturu do nabídky?',esc(t.name)+' nahradí recepturu vybrané směsi. Experimentální šarže se přesune do prodeje; starší šarže si ponechají původní profil.',()=>releaseTrial4(t.id),'Uvést do nabídky')});on('[data-competition]',b=>act(()=>enterCompetition4(b.dataset.competition),'Výsledek soutěže najdeš u receptury.'));if(el('growthLoan4'))el('growthLoan4').onclick=()=>confirmAction('Přijmout růstový úvěr?','Hotovost a dluh vzrostou o 2 miliony Kč. Banka bude vyžadovat dvoutýdenní rezervu a nezáporný průměr zisku. Po čtyřech týdnech bez nápravy účtuje pravidelný poplatek.',takeGrowthLoan4,'Přijmout úvěr');if(el('ipo4'))el('ipo4').onclick=()=>confirmAction('Uvést firmu na burzu?','Firma získá '+money(Math.max(1000000,companyValue())*.2)+' za 20 procentních bodů podílu zakladatele. Poplatek je 200 000 Kč. Každý kvartál se vyhodnotí závazek vůči investorům.',listCompany4,'Vstoupit na burzu');if(el('buyback4'))el('buyback4').onclick=()=>confirmAction('Odkoupit jeden procentní bod?','Cena '+money(Math.max(1000000,companyValue())*.01)+'. Podíl zakladatele se zvýší o jeden bod.',buyback4,'Odkoupit podíl');if(el('investorTarget4'))el('investorTarget4').onchange=()=>act(()=>setInvestorTarget4(el('investorTarget4').value),'Závazek uložen.');if(el('partnership4'))el('partnership4').onclick=()=>act(acceptPartnership4,'Obchodní partnerství uzavřeno.');if(el('declinePartnership4'))el('declinePartnership4').onclick=()=>act(()=>{guard();state.empire.partnership=null},'Nabídka odmítnuta.');};
render=function(){stopReplay4();UI3.render();if(view==='live')startReplay4();};
help=function(){UI3.help();const p=document.createElement('p');p.innerHTML='<strong>Edice 04:</strong> Živý provoz přehrává průběh posledního týdne. Plány vedení mají rozpočet a cíl ověřený po čtyřech výsledcích. Osobní příběhy mění vztahy a dovednosti. Kávová laboratoř využívá skutečné zásoby, výrobní kapacitu a degustaci před uvedením nové receptury. Soupeři investují podle své strategie a návratnosti. Trhy & burza ukazují hospodářský cyklus, nájmy, úvěrové podmínky a investorské závazky. Nový závazek investorům lze změnit pouze na začátku kvartálu.';el('modal').querySelector('h2').after(p);el('modal').querySelector('.eyelabel').textContent='KAVÁRNA · EDICE 04';};
el('help').onclick=help;
render();
